#include <stdio.h>
#include <limits.h>

int main(void) {
    int A, L, N;
    if (scanf("%d %d", &A, &L) != 2) return 0;
    if (scanf("%d", &N) != 1) return 0;

    long long photoArea = (long long)A * L;
    long long bestArea = LLONG_MAX;
    int bestId = -1;

    for (int i = 1; i <= N; i++) {
        int X, Y;
        if (scanf("%d %d", &X, &Y) != 2) return 0;

        int fits = (A <= X && L <= Y) || (A <= Y && L <= X);

        if (fits) {
            long long area = (long long)X * Y - photoArea;
            if (area < bestArea) {
                bestArea = area;
                bestId = i;
            }
        }
    }

    printf("%d\n", bestId);
    return 0;
}
```

